<style>
.fee-page{font-family:'Inter',sans-serif;color:#25313C}.fee-page *{box-sizing:border-box}.fee-head{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:20px}.fee-head h1{font-size:22px;font-weight:700;color:#123B5D;margin:0 0 5px}.fee-head p{font-size:13px;color:#64748B;margin:0}
.fee-btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:40px;padding:0 14px;border:1px solid #CBD5E1;border-radius:9px;background:#fff;color:#123B5D;font-size:13px;font-weight:600;text-decoration:none;cursor:pointer;white-space:nowrap}.fee-btn:hover{background:#F8FAFC;color:#123B5D}.fee-btn-primary{background:#123B5D;border-color:#123B5D;color:#fff}.fee-btn-primary:hover{background:#176B87;color:#fff}.fee-btn-danger{color:#DC2626}
.fee-card{background:#fff;border:1px solid #E2E8F0;border-radius:14px;padding:18px;margin-bottom:16px;min-width:0}.fee-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}.fee-kpi-label{font-size:12px;font-weight:600;color:#64748B;margin-bottom:10px}.fee-kpi-value{font-size:25px;font-weight:700;color:#123B5D}.fee-kpi-note{font-size:11px;color:#94A3B8;margin-top:8px}
.fee-section-title{font-size:15px;font-weight:700;color:#123B5D;margin:0}.fee-subtitle{font-size:11px;color:#94A3B8;margin-top:5px}.fee-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(280px,1fr);gap:16px}.fee-table-wrap{overflow-x:auto;margin-top:16px}.fee-table{width:100%;border-collapse:collapse;min-width:720px}.fee-table th{text-align:left;padding:12px;background:#F8FAFC;color:#64748B;font-size:11px;font-weight:700;border-bottom:1px solid #E2E8F0;white-space:nowrap}.fee-table td{padding:13px 12px;border-bottom:1px solid #F1F5F9;font-size:12px;color:#475569;vertical-align:middle}.fee-table tr:last-child td{border-bottom:0}
.fee-person{font-weight:650;color:#25313C}.fee-muted{font-size:11px;color:#94A3B8;margin-top:4px}.fee-actions{display:flex;align-items:center;gap:8px;white-space:nowrap}.fee-actions .fee-btn{min-height:36px;padding:0 11px}.fee-badge{display:inline-flex;padding:5px 9px;border-radius:20px;font-size:10px;font-weight:700;text-transform:capitalize;white-space:nowrap}.fee-paid{background:#DCFCE7;color:#166534}.fee-unpaid{background:#FEF3C7;color:#92400E}.fee-partial{background:#DBEAFE;color:#1D4ED8}
.fee-filters{display:flex;align-items:center;flex-wrap:wrap;gap:8px}.fee-input,.fee-select,.fee-textarea{width:100%;border:1px solid #CBD5E1;border-radius:8px;padding:10px 11px;font-family:inherit;font-size:13px;color:#334155;background:#fff;outline:none}.fee-input,.fee-select{height:40px}.fee-filters .fee-input,.fee-filters .fee-select{width:auto;min-width:145px;height:38px;font-size:12px}.fee-label{display:block;font-size:12px;font-weight:650;color:#475569;margin:0 0 7px}.fee-field{margin-bottom:15px}.fee-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.fee-alert{padding:11px 13px;border-radius:9px;margin-bottom:15px;font-size:12px;background:#FEF2F2;color:#991B1B;border:1px solid #FECACA}.fee-empty{text-align:center;padding:30px 15px;color:#94A3B8;font-size:12px}.fee-pagination{padding-top:14px}.fee-pagination nav p{font-size:12px;color:#64748B}
.fee-chart{height:190px;display:flex;align-items:flex-end;justify-content:space-around;gap:10px;padding:15px 5px 0;border-bottom:1px solid #E2E8F0;background:repeating-linear-gradient(to bottom,transparent 0,transparent 45px,#F1F5F9 46px,transparent 47px)}.fee-chart-item{flex:1;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:7px}.fee-chart-bar{width:min(32px,75%);background:#176B87;border-radius:5px 5px 0 0;min-height:2px}.fee-chart-label{font-size:10px;color:#64748B;padding-bottom:7px}.fee-line{display:flex;justify-content:space-between;gap:15px;padding:10px 0;border-bottom:1px solid #F1F5F9;font-size:12px}.fee-line:last-child{border-bottom:0}.fee-receipt{max-width:850px;margin:0 auto}.fee-receipt-head{display:flex;justify-content:space-between;gap:20px;border-bottom:2px solid #123B5D;padding-bottom:18px;margin-bottom:18px}
@media(max-width:1000px){.fee-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.fee-grid{grid-template-columns:1fr}}@media(max-width:600px){.fee-head{align-items:flex-start;flex-direction:column}.fee-kpis{gap:9px}.fee-card{padding:14px}.fee-kpi-value{font-size:21px}.fee-form-grid{grid-template-columns:1fr}.fee-filters>*{width:100%!important}}@media print{.fee-no-print,.sidebar,.navbar{display:none!important}.fee-page{padding:0!important}.fee-card{border:0!important}.fee-receipt{max-width:none}}
</style>